    def __init__(self, type, skip_checks=False, **kwargs):
        spec = _META_SPEC_BY_TYPE[type]
        self_vars = vars(self)
        self_vars['type'] = type

        if not skip_checks:
            for name in kwargs:
                if name not in spec.settable_attributes:
                    raise ValueError(
                        '{} is not a valid argument for this message type'.format(
                            name))

