            self_vars[name] = value
        self_vars['time'] = 0

        for name, value in kwargs.items():
            self._setattr(name, value)

    def copy(self, **overrides):
        if not overrides:
            msg = self.__class__.__new__(self.__class__)
            vars(msg).update(vars(self))
            return msg

